import * as React from "react"
import Layout from "../components/layout"
import PageTitle from "../components/PageTitle"
import Seo from "../components/seo"
import Quote from "../components/construct/Quote"

import ServiceDetails from "../components/ServiceDetails"

const ServiceTemplate = ({ location, pageContext }) => {
  const { product, products, contacto } = pageContext
  return (
    <Layout>
      <Seo title={product.title} />
      <PageTitle title={product.title} />
      <ServiceDetails
        location={location}
        description={product.description_large}
        sidebar={products}
        title={product.title}
        image={product.image}
        dataItem={product.data}
      />
      <Quote data={contacto.nodes} />
    </Layout>
  )
}

export default ServiceTemplate
